def confronta(ordine, fattura):
    diverse = [o for o, f in zip(ordine, fattura) if (o['q'], o['prezzo']) != (f['q'], f['prezzo'])]
    eccesso = round(sum(f['q'] * f['prezzo'] for f in fattura) - sum(o['q'] * o['prezzo'] for o in ordine), 2)
    return {'righe_diverse': len(diverse), 'importo_in_eccesso': eccesso, 'esito': 'contesta' if diverse else 'approva'}
